contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint a, uint b) public payable {
        c.SetMinSum(a); if (__ESBMC_reverted()) return;
        c.SetMinSum(b); if (__ESBMC_reverted()) return;
        assert(c.MinSum() == b);
    }
}

